const views={"terminal":View7};
export interface ArtemisNotFoundPagesProps{className?:string;variant?:"terminal";}
export function ArtemisNotFoundPages({className,variant="terminal"}:ArtemisNotFoundPagesProps){const View=views[variant];return <ArtemisScope className={["art:min-h-dvh art:[&>section]:min-h-dvh",className].filter(Boolean).join(" ")}><View/></ArtemisScope>;}

"use client";
// @zeus-internal
import { useEffect, useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PANEL, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
export default function NotFoundPagesTerminal() {
    const reduce = useReducedMotion();
    const [rowsShown, setRowsShown] = useState(false);
    const [errorShown, setErrorShown] = useState(false);
    const [actionShown, setActionShown] = useState(false);
    useEffect(() => {
        const rows = setTimeout(() => setRowsShown(true), 60);
        const error = setTimeout(() => setErrorShown(true), 180);
        const action = setTimeout(() => setActionShown(true), 320);
        return () => { clearTimeout(rows); clearTimeout(error); clearTimeout(action); };
    }, []);
    const press = { whileHover: reduce ? undefined : { scale: 1.01 }, whileTap: reduce ? undefined : { scale: 0.99 }, transition: ARTEMIS_SPRING_PRESS };
    return (<>
      <section className="art:flex art:min-h-[680px] art:w-full art:flex-col art:bg-background art:font-mono art:text-foreground">
        <header className="art:flex art:min-h-16 art:flex-wrap art:items-center art:justify-between art:gap-3 art:border-border art:border-b art:px-5 art:py-3 art:@min-[640px]/artemis:px-8">
          <div className="art:flex art:items-center art:gap-3">
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-terminal art:size-4 art:text-foreground" aria-hidden="true">
              <path d="M12 19h8"/>
              <path d="m4 17 6-6-6-6"/>
            </svg>
            <span className="art:text-xs">
              {"workspace-web"}
            </span>
            <span className="art:text-xs art:text-muted-foreground">
              {"/ production"}
            </span>
          </div>
          <span className="art:border art:border-foreground/20 art:px-2 art:py-1 art:text-xs art:text-foreground art:uppercase art:tracking-[0.16em]">
            {"route failed"}
          </span>
        </header>
        <div className="art:grid art:flex-1 art:@min-[1024px]/artemis:grid-cols-[0.58fr_0.42fr]">
          <div className="art:flex art:flex-col art:justify-between art:border-border art:border-b art:p-5 art:@min-[640px]/artemis:p-8 art:@min-[1024px]/artemis:border-r art:@min-[1024px]/artemis:border-b-0 art:@min-[1024px]/artemis:p-12">
            <div>
              <p className="art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.18em]">
                {"request trace"}
              </p>
              <div className="art:mt-7 art:space-y-0 art:border-border art:border-y">
                <motion.div initial={{ opacity: 0, x: -12 }} animate={{ opacity: rowsShown || reduce ? 1 : 0, x: rowsShown || reduce ? 0 : -12 }} transition={{ duration: reduce ? 0 : 0.3, ease: ARTEMIS_EASE_OUT, delay: reduce ? 0 : 0 * 0.07 }} className="art:grid art:grid-cols-[2.5rem_1fr_auto] art:items-center art:gap-4 art:border-border art:border-b art:py-4 art:text-xs art:last:border-b-0">
                  <span className="art:text-muted-foreground">
                    {"01"}
                  </span>
                  <span>
                    {"resolve host"}
                  </span>
                  <span className="art:text-success">
                    {"["}
                    {"ok"}
                    {"]"}
                  </span>
                </motion.div>
                <motion.div initial={{ opacity: 0, x: -12 }} animate={{ opacity: rowsShown || reduce ? 1 : 0, x: rowsShown || reduce ? 0 : -12 }} transition={{ duration: reduce ? 0 : 0.3, ease: ARTEMIS_EASE_OUT, delay: reduce ? 0 : 1 * 0.07 }} className="art:grid art:grid-cols-[2.5rem_1fr_auto] art:items-center art:gap-4 art:border-border art:border-b art:py-4 art:text-xs art:last:border-b-0">
                  <span className="art:text-muted-foreground">
                    {"02"}
                  </span>
                  <span>
                    {"match route"}
                  </span>
                  <span className="art:text-destructive">
                    {"["}
                    {"miss"}
                    {"]"}
                  </span>
                </motion.div>
                <motion.div initial={{ opacity: 0, x: -12 }} animate={{ opacity: rowsShown || reduce ? 1 : 0, x: rowsShown || reduce ? 0 : -12 }} transition={{ duration: reduce ? 0 : 0.3, ease: ARTEMIS_EASE_OUT, delay: reduce ? 0 : 2 * 0.07 }} className="art:grid art:grid-cols-[2.5rem_1fr_auto] art:items-center art:gap-4 art:border-border art:border-b art:py-4 art:text-xs art:last:border-b-0">
                  <span className="art:text-muted-foreground">
                    {"03"}
                  </span>
                  <span>
                    {"search fallback"}
                  </span>
                  <span className="art:text-destructive">
                    {"["}
                    {"empty"}
                    {"]"}
                  </span>
                </motion.div>
              </div>
            </div>
            <motion.div initial={{ opacity: 0, y: 12 }} animate={{ opacity: actionShown || reduce ? 1 : 0, y: actionShown || reduce ? 0 : 12 }} transition={reduce ? { duration: 0 } : ARTEMIS_SPRING_PANEL} className="art:mt-10">
              <div className="art:flex art:flex-wrap art:gap-3">
                <motion.a {...press} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:gap-2 art:px-6 art:text-base art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:bg-primary art:text-primary-foreground art:hover:bg-primary/85 art:h-9 art:rounded-full" href="/" tabIndex={0}>
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-rotate-ccw art:size-4" aria-hidden="true">
                    <path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/>
                    <path d="M3 3v5h5"/>
                  </svg>
                  {"cd /home"}
                </motion.a>
              </div>
            </motion.div>
          </div>
          <motion.div initial={{ opacity: 0 }} animate={{ opacity: errorShown || reduce ? 1 : 0 }} transition={{ duration: reduce ? 0 : 0.35, ease: ARTEMIS_EASE_OUT }} className="art:relative art:flex art:min-h-[360px] art:flex-col art:justify-between art:overflow-hidden art:p-5 art:@min-[640px]/artemis:p-8 art:@min-[1024px]/artemis:min-h-0 art:@min-[1024px]/artemis:p-12">
            <div>
              <p className="art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.18em]">
                {"stderr"}
              </p>
              <p className="art:mt-6 art:text-9xl art:text-foreground art:leading-[0.75] art:tracking-[-0.09em]">
                {"404"}
              </p>
              <h1 className="art:mt-8 art:max-w-md art:text-balance art:font-sans art:leading-tight art:tracking-[-0.03em] art:text-4xl art:@min-[768px]/artemis:text-5xl art:font-medium">
                {"Route not found."}
              </h1>
            </div>
          </motion.div>
        </div>
      </section>
    </>);
}
